void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy; 
    uv.y = fract(uv.y);
    vec3 col0 = texture(iChannel0,uv).rgb;
    vec3 col = col0;


    uv.y -= 0.5;
    uv.y = 1.0-abs(uv.y-0.5);
    uv.x = 1.0-abs(uv.x-0.5);

    float a = 0.5*iTime;
    uv *= mat2(cos(a),sin(a),-sin(a),cos(a));

    uv.y-=0.5*uv.x-0.5+0.5*sin(0.3*iTime);
    uv.y = fract(uv.y);
    uv.x += 0.5*uv.y+0.2*iTime;
    uv.x = fract(uv.x);

    uv = mix(uv,vec2(length(uv-0.5),atan(uv.x-0.5,uv.y-0.5)/3.14159),0.0+(smoothstep(0.0,1.0,sin(iTime)))*uv.y);


    float h = 0.0;
    for(int i=0;i<8;i++)
    {
        float size = 100.0+ 5.0*float(i);
        float q = floor( size * uv.x ) / size;
        float h0=textureLod(iChannel1,vec2(q,0.1*float(i)+0.01*iTime*(0.0*float(i)+1.0)),1.0-0.3*float(i)).r;
        //h0=floor(h0*50.0)/50.0;
        if(i>=1) col *= 0.5+0.5*smoothstep( 0.0, 0.1, h0 + 0.09 * float(i) - uv.y );
        if( h0 + 0.09 * float(i) < uv.y )
        {
            col = texture(iChannel0,vec2(q+0.5,0.5+0.01*float(i)+iTime)).rgb * ((float(i)+0.5)*0.2);
        }

        h=h0;
    }

    col = mix(col,col0,smoothstep(0.75,1.0,uv.y));

    fragColor = vec4(col,1.0);
}
